UPDATE requests SET pro=suggested_pro,status='Asignado',updated=strftime('%Y-%m-%dT%H:%M:%fZ','now'),payload=json_insert(payload,'$.history[#]',json_object('status','Asignado','at',strftime('%Y-%m-%dT%H:%M:%fZ','now'))) WHERE status='Pendiente' AND pro IS NULL AND suggested_pro IN (SELECT id FROM professionals WHERE approval_status='approved') AND json_extract(payload,'$.service')=(SELECT service FROM professionals WHERE id=requests.suggested_pro);
